before:
```react
function ModeButton({active, onChoose}) {
  return <button aria-pressed={active} onClick={onChoose}>Quiet mode</button>;
}
function App() {
  const [quiet, setQuiet] = React.useState(false);
  return <main>
    <ModeButton active={quiet} onChoose={() => setQuiet(q => !q)} />
    <p>{quiet ? "Quiet" : "Normal"}</p>
  </main>;
}
```
The button and paragraph read the same parent value.

after:
```react
function ModeButton({ active, onChoose }) {
  return <button aria-pressed={active} onClick={onChoose}>Quiet mode</button>;
}
function App() {
  const [quiet, setQuiet] = React.useState(false);
  return (
    <main>
      <ModeButton active={quiet} onChoose={() => setQuiet(q => !q)} />
      <p>{quiet ? "Quiet" : "Normal"}</p>
    </main>
  );
}
```
The button and paragraph use the same state. Clicking changes both the pressed state and the message.
